async function GETOperation(
  _request: Request,
  { params }: { params: Promise<{ id: string }> },
): Promise<NextResponse> {
  const movementMasterId = (await params).id.trim();
  if (!movementMasterId) {
    return NextResponse.json(
      { error: "Movement ID is required." },
      { status: 400 },
    );
  }
  try {
    const googleSheetsService = createGoogleSheetsServiceFromConfig(getConfig());
    const records = await getMovementItems({
      googleSheetsService,
      movementMasterId,
    });
    if (records.length === 0 && !await movementExists({ googleSheetsService, movementMasterId })) {
      return NextResponse.json(
        { error: "Movement was not found." },
        { status: 404 },
      );
    }
    return NextResponse.json({ records });
  } catch (error) {
    return movementError("load", movementMasterId, error);
  }
}

async function PATCHOperation(
  request: Request,
  { params }: { params: Promise<{ id: string }> },
): Promise<NextResponse> {
  const movementMasterId = (await params).id.trim();
  const body = await readJson(request);
  if (!movementMasterId || body?.status !== "delivered") {
    return NextResponse.json(
      { error: "Movement ID and delivered status are required." },
      { status: 400 },
    );
  }
  try {
    const result = await markMovementDelivered({
      googleSheetsService: createGoogleSheetsServiceFromConfig(getConfig()),
      movementMasterId,
    });
    if (!result) {
      return NextResponse.json(
        { error: "Movement was not found." },
        { status: 404 },
      );
    }
    return NextResponse.json(result);
  } catch (error) {
    if (error instanceof MovementQuantityRequiredError) {
      return NextResponse.json({ error: error.message }, { status: 409 });
    }
    return movementError("update", movementMasterId, error);
  }
}

async function readJson(request: Request): Promise<Record<string, unknown> | null> {
  try {
    const value: unknown = await request.json();
    return typeof value === "object" && value !== null && !Array.isArray(value)
      ? (value as Record<string, unknown>)
      : null;
  } catch {
    return null;
  }
}

function movementError(
  operation: string,
  movementMasterId: string,
  error: unknown,
): NextResponse {
  console.error(`Failed to ${operation} movement`, {
    error: error instanceof Error ? error.message : String(error),
    movementMasterId,
  });
  return NextResponse.json(
    { error: `Failed to ${operation} movement.` },
    { status: 500 },
  );
}

export const GET = withPersistence(GETOperation);
export const PATCH = withPersistence(PATCHOperation);

